[URL Rewrite]
request if ${url} ~= /^https?:\/\/j-image\.missfresh\.cn\/img_(.+)\.gif$/i then reject(404)
request if ${url} ~= /^https?:\/\/j-image\.missfresh\.cn\/img_(.+)\.(jpg|jpeg|gif|png)\?iopcmd=convert&dst=webp&q=85$/i then reject(404)

[MITM]
hostname = %APPEND% j-image.missfresh.cn
